import{_ as e}from"./chunks/artisan-avatar.Bv6PR6ng.js";import{c as s,$ as o,Q as n,j as l,g as r,o as i,n as c,m as d}from"./chunks/framework.Ce_49mA8.js";const x=JSON.parse('{"title":"О разработчиках","description":"История создания ОмниКрафт ЕРП, ремесленная мастерская и практические принципы разработки.","frontmatter":{"title":"О разработчиках","description":"История создания ОмниКрафт ЕРП, ремесленная мастерская и практические принципы разработки.","order":18,"aside":false,"lastUpdated":false,"pageClass":"page-no-date","datePublished":"2026-11-14"},"headers":[],"relativePath":"ru/docs/about.md","filePath":"ru/docs/about.md"}'),p={name:"ru/docs/about.md"},h={id:"о-разработчиках",tabindex:"-1"};function g(u,a,m,f,k,b){const t=o("DocIcon");return n(),l("div",null,[r("h1",h,[i(t,{name:"about"}),a[0]||(a[0]=c(" О разработчиках ",-1)),a[1]||(a[1]=r("a",{class:"header-anchor",href:"#о-разработчиках","aria-label":'Permalink to "О разработчиках"'},"​",-1))]),a[2]||(a[2]=d('<p><strong>ОмниКрафт ЕРП</strong> создана в действующей ремесленной мастерской — среди станков, оборудования и реальных материалов, где на практике проверяются надёжность и удобство каждого решения.</p><div class="maker-profile-card"><div class="maker-avatar-wrap"><img src="'+e+'" alt="Николай Мурашкин — создатель мастерской Н. Мурашкин и автор ОмниКрафт ЕРП" class="maker-avatar-img"><span class="maker-avatar-badge">Мастер и архитектор</span></div><div class="maker-info"><h3 class="maker-name">Николай Мурашкин</h3><p class="maker-role">Основатель ремесленной мастерской <strong>Н. Мурашкин</strong> и автор платформы <strong>ОмниКрафт ЕРП</strong></p><p class="maker-quote">«Программа изначально создавалась для нужд собственного бизнеса и мастерской: требовалось уйти от ручных расчётов в таблицах, точно видеть себестоимость каждого изделия и держать под контролем финансы. В основу архитектуры легли практические алгоритмы, которые ежедневно работают в нашем собственном деле.»</p><div class="maker-links"><a href="https://nmurashkin.ru" target="_blank" rel="noopener noreferrer" class="maker-link-btn"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"></circle><line x1="2" y1="12" x2="22" y2="12"></line><path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"></path></svg> Мастерская Н. Мурашкин </a><a href="https://github.com/NikMurashkin/OmniCraft-ERP-Releases" target="_blank" rel="noopener noreferrer" class="maker-link-btn"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M9 19c-5 1.5-5-2.5-7-3m14 6v-3.87a3.37 3.37 0 0 0-.94-2.61c3.14-.35 6.44-1.54 6.44-7A5.44 5.44 0 0 0 20 4.77 5.07 5.07 0 0 0 19.91 1S18.73.65 16 2.48a13.38 13.38 0 0 0-7 0C6.27.65 5.09 1 5.09 1A5.07 5.07 0 0 0 5 4.77a5.44 5.44 0 0 0-1.5 3.78c0 5.42 3.3 6.61 6.44 7A3.37 3.37 0 0 0 9 18.13V22"></path></svg> Репозиторий релизов </a><a href="/ru/docs/contacts" class="maker-link-btn"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 11.5a8.38 8.38 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.38 8.38 0 0 1-3.8-.9L3 21l1.9-5.7a8.38 8.38 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.38 8.38 0 0 1 3.8-.9h.5a8.48 8.48 0 0 1 8 8v.5z"></path></svg> Контакты и реквизиты </a></div></div></div><hr><h2 id="принципы-разработки" tabindex="-1">Принципы разработки <a class="header-anchor" href="#принципы-разработки" aria-label="Permalink to &quot;Принципы разработки&quot;">​</a></h2><p>В мастерской и в разработке программ мы придерживаемся единого подхода: инструмент должен быть надёжным, предсказуемым и служить годами.</p><p>ОмниКрафт ЕРП проектировалась как практичный инструмент для предпринимателей и мастеров. В основу программы заложены четыре принципа:</p><ul class="craft-feature-list"><li><span class="craft-list-bullet"></span><div><strong>Надёжность хранения данных:</strong><br> Локальная база данных с автоматическим сохранением каждой операции и резервным копированием защищает записи при сбоях оборудования или отключении питания. </div></li><li><span class="craft-list-bullet"></span><div><strong>Локальное хранение и автономность:</strong><br> База клиентов, финансовые проводки, остатки склада и технологические карты хранятся на вашем компьютере. Программа работает без постоянного подключения к сети и не зависит от сторонних серверов. </div></li><li><span class="craft-list-bullet"></span><div><strong>Бессрочное владение лицензией:</strong><br> Программа приобретается в собственность на выбранный период или бессрочно. Доступ к накопленным коммерческим данным не зависит от регулярных платежей по подписке. </div></li><li><span class="craft-list-bullet"></span><div><strong>Точный и прозрачный расчёт:</strong><br> Программа рассчитывает себестоимость сырья методом скользящей средней, учитывает амортизацию оборудования, накладные расходы и затраченное рабочее время. </div></li></ul><hr><h2 id="предыстория-создания" tabindex="-1">Предыстория создания <a class="header-anchor" href="#предыстория-создания" aria-label="Permalink to &quot;Предыстория создания&quot;">​</a></h2><p>До разработки программы учёт в мастерской вёлся в электронных таблицах и блокнотах. Когда требовалось рассчитать себестоимость изделия с учётом доставки материалов, износа оборудования и рабочего времени, приходилось либо тратить время на ручные подсчёты, либо оценивать затраты приблизительно.</p><p>Для ежедневной работы требовался специализированный инструмент:</p><ol><li><strong>Расчёт себестоимости материалов:</strong> автоматический пересчёт стоимости остатков методом скользящей средней, распределение расходов на доставку и списание сырья при выпуске продукции.</li><li><strong>Учёт расходов и окупаемости:</strong> расчёт точки безубыточности, себестоимости часа работы и распределения постоянных расходов.</li><li><strong>Контроль и сохранность данных:</strong> работа с собственной базой данных без риска внешних изменений условий обслуживания или передачи информации третьим лицам.</li></ol><p>Так появилась ОмниКрафт ЕРП — система учёта для мастерских, сервисных центров и небольших производств.</p><hr><h2 id="техническая-основа" tabindex="-1">Техническая основа <a class="header-anchor" href="#техническая-основа" aria-label="Permalink to &quot;Техническая основа&quot;">​</a></h2><p>Платформа спроектирована по стандартам надёжного прикладного программного обеспечения:</p><ul><li><strong>Локальная база данных:</strong> встроенная база данных обеспечивает быстрый отклик программы, стабильно работает на вашем компьютере и не требует установки сторонних серверов.</li><li><strong>Автономность:</strong> в программе полностью отсутствует скрытая отправка пользовательских данных, списков клиентов или финансовых записей на удалённые серверы.</li><li><strong>Открытая история выпусков:</strong> обновления, журнал изменений и контрольные суммы установочных файлов регулярно публикуются в официальном репозитории на GitHub.</li></ul><hr><h2 id="связь-с-разработчиком" tabindex="-1">Связь с разработчиком <a class="header-anchor" href="#связь-с-разработчиком" aria-label="Permalink to &quot;Связь с разработчиком&quot;">​</a></h2><p>Мы продолжаем развивать программу, опираясь на практику собственной мастерской и обратную связь коллег по производственному и сервисному делу.</p><p>Если у вас есть предложения по развитию программы или вопросы по её работе:</p><ul><li><strong>Официальный сайт:</strong> <a href="https://omnicraft-erp.com" target="_blank" rel="noreferrer">omnicraft-erp.com</a></li><li><strong>Репозиторий релизов:</strong> <a href="https://github.com/NikMurashkin/OmniCraft-ERP-Releases" target="_blank" rel="noreferrer">OmniCraft-ERP-Releases (GitHub)</a></li><li><strong>Контакты и реквизиты разработчика:</strong> <a href="/ru/docs/contacts">Раздел контактов</a></li><li><strong>Мастерская Н. Мурашкин:</strong> <a href="https://nmurashkin.ru" target="_blank" rel="noreferrer">nmurashkin.ru</a></li></ul>',22))])}const P=s(p,[["render",g]]);export{x as __pageData,P as default};
